head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDSTF10004";
scwin.scbHeadTag = undefined;
scwin.scbScript = undefined;
scwin.scbRandom = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.scbHeadTag =document.getElementsByTagName("head")[0]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf10004' }); }

try { scwin.scbScript =document.createElement('script'); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf10004' }); }

try { scwin.scbRandom =(Math.random().toString(36).slice(-8)); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf10004' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf10004.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
///////// 4. 서브미션 콜백 영역 /////////
///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name onload
 * @description onload 처리
 * @returns {void}
 * @hidden N
 */
scwin.onload = function () {
    setTimeout(function(){ scwin.check() }, 100);
};

/**
 * @method
 * @name check
 * @description check 처리
 * @returns {void}
 * @hidden N
 */
scwin.check = function () {
    if (typeof ShiftCrossBrowser_BrowserDetect !== "undefined") {
        if (ShiftCrossBrowser_BrowserDetect.browser === "Explorer" && ShiftCrossBrowser_BrowserDetect.browserVersion === "x86") {
            const sAcptNo = "null";
            const gAskScrenID = "null";
            const gAccssAuthTpCd = "null";
            // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
            $c.win.setPageFrameSrc($c.win.getFrame(), (function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })("./JLDSTF10004_1.jsp?AcptNo=" + sAcptNo + "&gAccssAuthTpCd=" + gAccssAuthTpCd + "&gAskScrenID=" + gAskScrenID));
        }
    }
};
